package cl.pasteshifter.orbital;

import android.util.Base64;
import java.nio.charset.StandardCharsets;
import java.util.Iterator;
import java.util.Locale;
import java.util.UUID;
import org.json.JSONException;
import org.json.JSONObject;

/** Strict parser for the ephemeral pairing-v1 QR generated by the Mac app. */
public final class OrbitalPairingQr {
    public final UUID pairingId;
    public final UUID macId;
    public final byte[] certificateFingerprintSha256;
    public final byte[] pairingSecret;
    public final long expiresAtMilliseconds;

    private OrbitalPairingQr(UUID pairingId, UUID macId, byte[] fingerprint,
                             byte[] secret, long expiresAtMilliseconds) {
        this.pairingId = pairingId;
        this.macId = macId;
        this.certificateFingerprintSha256 = fingerprint.clone();
        this.pairingSecret = secret.clone();
        this.expiresAtMilliseconds = expiresAtMilliseconds;
    }

    public static OrbitalPairingQr parse(String rawJson, long nowMilliseconds) throws JSONException {
        if (rawJson == null || rawJson.getBytes(StandardCharsets.UTF_8).length > 4096) {
            throw new JSONException("Pairing QR is too large");
        }
        JSONObject json = new JSONObject(rawJson);
        requireKeys(json, "version", "pairingID", "localDeviceID", "certificateFingerprintSHA256",
                "pairingSecret", "expiresAtMilliseconds");
        Object version = json.opt("version");
        if (!(version instanceof Number) || ((Number) version).intValue() != 1
                || ((Number) version).doubleValue() != 1.0) throw new JSONException("Unsupported pairing version");
        UUID pairingId = strictUuid(json, "pairingID");
        UUID macId = strictUuid(json, "localDeviceID");
        Object fingerprintValue = json.opt("certificateFingerprintSHA256");
        if (!(fingerprintValue instanceof String)) throw new JSONException("Invalid certificate fingerprint");
        String hex = (String) fingerprintValue;
        if (!hex.matches("[0-9a-f]{64}")) throw new JSONException("Invalid certificate fingerprint");
        byte[] fingerprint = decodeHex(hex);
        byte[] secret;
        Object secretValue = json.opt("pairingSecret");
        if (!(secretValue instanceof String) || ((String) secretValue).length() != 44) {
            throw new JSONException("Invalid pairing secret");
        }
        try {
            secret = Base64.decode((String) secretValue, Base64.NO_WRAP);
        } catch (IllegalArgumentException e) {
            throw new JSONException("Invalid pairing secret");
        }
        if (secret.length != 32 || !Base64.encodeToString(secret, Base64.NO_WRAP).equals(secretValue)) {
            throw new JSONException("Invalid pairing secret length or encoding");
        }
        Object expiryValue = json.opt("expiresAtMilliseconds");
        if (!(expiryValue instanceof Number)
                || ((Number) expiryValue).doubleValue() != ((Number) expiryValue).longValue()) {
            throw new JSONException("Invalid pairing expiry");
        }
        long expiry = ((Number) expiryValue).longValue();
        if (expiry <= nowMilliseconds || expiry > nowMilliseconds + 121_000L) {
            throw new JSONException("Pairing QR is expired or has an invalid lifetime");
        }
        OrbitalPairingQr result = new OrbitalPairingQr(pairingId, macId, fingerprint, secret, expiry);
        java.util.Arrays.fill(secret, (byte) 0);
        return result;
    }

    public boolean isStillValid(long nowMilliseconds) {
        return expiresAtMilliseconds > nowMilliseconds;
    }

    public void clearSecret() { java.util.Arrays.fill(pairingSecret, (byte) 0); }

    private static UUID strictUuid(JSONObject json, String key) throws JSONException {
        Object value = json.opt(key);
        if (!(value instanceof String)
                || !((String) value).matches("(?i)[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}")) {
            throw new JSONException("Invalid UUID field " + key);
        }
        return UUID.fromString((String) value);
    }

    private static void requireKeys(JSONObject object, String... expected) throws JSONException {
        java.util.HashSet<String> allowed = new java.util.HashSet<>();
        java.util.Collections.addAll(allowed, expected);
        Iterator<String> keys = object.keys();
        while (keys.hasNext()) if (!allowed.remove(keys.next())) throw new JSONException("Unknown pairing field");
        if (!allowed.isEmpty()) throw new JSONException("Missing pairing field");
    }

    private static byte[] decodeHex(String value) {
        byte[] result = new byte[value.length() / 2];
        for (int i = 0; i < result.length; i++) {
            result[i] = (byte) Integer.parseInt(value.substring(i * 2, i * 2 + 2), 16);
        }
        return result;
    }
}
